#!/usr/bin/env bash
# MUT-4 (r101) — capture C3 Y-measurement outputs with real Godot headless runs.
# Scratch project: /tmp/r101-mut04/proj (generated by mut04_gen.py).
# XDG override keeps all user-dir writes inside the scratch tree; the fixture's
# env diag does not reference XDG, and the unpatched_x0 receipt must equal the
# landed x0 pin byte-for-byte (fidelity anchor checked by mut04_classify.py).
set -u
OUT=/tmp/r101-mut04/out
PROJ=/tmp/r101-mut04/proj
mkdir -p "$OUT" /tmp/r101-mut04/xdg-data
export XDG_DATA_HOME=/tmp/r101-mut04/xdg-data
: > "$OUT/run_log.txt"

run() {
  local name=$1 script=$2; shift 2
  local t0 t1 rc
  t0=$(date +%s.%N)
  timeout 120 godot --headless --path "$PROJ" --script "res://$script" -- "$@" \
    > "$OUT/$name.stdout" 2> "$OUT/$name.stderr"
  rc=$?
  t1=$(date +%s.%N)
  echo "$rc" > "$OUT/$name.rc"
  printf '%s rc=%s secs=%.1f cmd=godot --headless --path %s --script res://%s -- %s\n' \
    "$name" "$rc" "$(echo "$t1 - $t0" | bc)" "$PROJ" "$script" "$*" >> "$OUT/run_log.txt"
}

run unpatched_x0    r95b_order.gd      --arm=celloff --off=0
run unpatched_y1000 r95b_order.gd      --arm=celloff --off=0 --offy=1000
run base_offy0      ytrans_base.gd     --arm=celloff --off=0 --offy=0
run base_offy1000   ytrans_base.gd     --arm=celloff --off=0 --offy=1000
run m1_echo         ytrans_m1_echo.gd  --arm=celloff --off=0 --offy=1000
run m2_omitkey      ytrans_m2_omitkey.gd --arm=celloff --off=0 --offy=1000
run m3_omity        ytrans_m3_omity.gd --arm=celloff --off=0 --offy=1000
run m4_swapkeys     ytrans_m4_swapkeys.gd --arm=celloff --off=0 --offy=1000
run m5_noenv        ytrans_m5_noenv.gd --arm=celloff --off=0 --offy=1000

cat "$OUT/run_log.txt"
